import json
import math
import os
import re
import sys
from datetime import datetime, timezone

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
EPOCH = datetime(1970, 1, 1)


def parse_time(text):
    text = text.strip().replace("T", " ")
    return int((datetime.strptime(text, "%Y-%m-%d %H:%M:%S") - EPOCH).total_seconds())


def parse_tz(text):
    text = text.strip()
    if text == "Z":
        return 0
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return sign * (int(hours) * 3600 + int(minutes) * 60)


def is_missing(text):
    low = text.lower()
    if low in ("", "nan", "---"):
        return True
    return re.fullmatch(r"-9999(\.0*)?", text) is not None


def convert(quantity, unit, value):
    if quantity == "temp":
        if unit == "degF":
            return (value - 32) * 5 / 9
        if unit == "K":
            return value - 273.15
    elif quantity == "rh":
        if unit == "frac":
            return value * 100
    elif quantity == "pres":
        if unit == "kPa":
            return value * 10
        if unit == "inHg":
            return value * 33.8638866667
        if unit == "mmHg":
            return value * 1.33322387415
    elif quantity == "wspd":
        if unit == "kmh":
            return value / 3.6
        if unit == "kn":
            return value * 1852 / 3600
        if unit == "mph":
            return value * 0.44704
    elif quantity == "rain":
        if unit.startswith("tips:"):
            return value * float(unit[5:])
    return value


def read_file(path):
    with open(path, "rb") as handle:
        text = handle.read().decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    header = {}
    columns = None
    units = {}
    rows = []
    syncs = []
    for line in text.splitlines():
        if not line.strip():
            continue
        if line.startswith("#"):
            match = DIRECTIVE.match(line)
            if not match:
                continue
            key, value = match.group(1), match.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                header[key] = value
            elif key == "columns":
                columns = [c.strip() for c in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        name, unit = pair.split("=", 1)
                        units[name] = unit
            elif key == "sync":
                parts = {}
                for part in value.split():
                    if "=" in part:
                        name, val = part.split("=", 1)
                        parts[name] = val
                if "logger" in parts and "ref" in parts:
                    syncs.append((parse_time(parts["logger"]),
                                  parse_time(parts["ref"].rstrip("Z"))))
            continue
        fields = [f.strip() for f in line.split(",")]
        values = {}
        logger_time = None
        for name, field in zip(columns, fields):
            if name == "time":
                logger_time = parse_time(field)
            elif name in RANGES:
                if is_missing(field):
                    continue
                try:
                    value = float(field)
                except ValueError:
                    continue
                value = convert(name, units.get(name, ""), value)
                low, high = RANGES[name]
                if math.isfinite(value) and low <= value <= high:
                    values[name] = value
        rows.append((logger_time, values))
    if "station" not in header:
        return None
    offset = parse_tz(header["tz"])
    return {
        "station": header["station"],
        "upload": int(header["upload"]),
        "interval": int(header["interval"]),
        "rows": [(t - offset, v) for t, v in rows],
        "syncs": [(t - offset, ref) for t, ref in syncs],
    }


def offset_at(points, instant):
    if not points:
        return 0
    if instant <= points[0][0]:
        return points[0][1]
    if instant >= points[-1][0]:
        return points[-1][1]
    for index in range(len(points) - 1):
        t1, o1 = points[index]
        t2, o2 = points[index + 1]
        if t1 <= instant <= t2:
            if instant == t2:
                return o2
            return (o1 * (t2 - t1) + (o2 - o1) * (instant - t1)) // (t2 - t1)
    return points[-1][1]


def hour_end(seconds):
    return -((-seconds) // 3600) * 3600


def stat(values, n, expected):
    return n * 4 >= expected * 3


def build_station(files):
    interval = files[0]["interval"]
    expected = 3600 / interval
    samples = {}
    syncs = {}
    for info in sorted(files, key=lambda f: f["upload"]):
        for instant, values in info["rows"]:
            samples[instant] = values
        for instant, ref in info["syncs"]:
            syncs[instant] = ref - instant
    points = sorted(syncs.items())
    rows = []
    for instant, values in samples.items():
        corrected = instant + offset_at(points, instant)
        rows.append((corrected, instant, values))
    rows.sort(key=lambda r: (r[0], r[1]))

    per_hour = {}
    previous = None
    for corrected, _, values in rows:
        entry = per_hour.setdefault(hour_end(corrected), {
            "readings": {q: [] for q in QUANTITIES}, "vectors": [], "incs": []})
        for quantity, value in values.items():
            entry["readings"][quantity].append(value)
        if "wdir" in values and values.get("wspd", 0) > 0:
            angle = math.radians(values["wdir"])
            entry["vectors"].append((math.sin(angle), math.cos(angle)))
        if "rain" in values:
            current = values["rain"]
            if previous is not None and (corrected - previous[0]) * 2 <= 5 * interval:
                prev_value = previous[1]
                entry["incs"].append(current - prev_value if current >= prev_value else current)
            previous = (corrected, current)

    first, last = min(per_hour), max(per_hour)
    hours = []
    for hour in range(first, last + 1, 3600):
        entry = per_hour.get(hour)
        item = {"hour": datetime.fromtimestamp(hour, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
        for quantity in QUANTITIES:
            readings = entry["readings"][quantity] if entry else []
            n = len(readings)
            value = None
            if n and stat(readings, n, expected):
                if quantity == "wdir":
                    if entry["vectors"]:
                        east = sum(v[0] for v in entry["vectors"])
                        north = sum(v[1] for v in entry["vectors"])
                        value = round(math.degrees(math.atan2(east, north)) % 360, 2)
                        if value >= 360:
                            value = 0.0
                elif quantity == "rain":
                    value = round(sum(entry["incs"]), 2)
                else:
                    value = round(sum(readings) / n, 2)
            item[quantity] = {"value": value, "n": n}
        hours.append(item)
    return {"station": files[0]["station"], "interval_s": interval, "hours": hours}


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    by_station = {}
    for name in sorted(os.listdir(input_dir)):
        path = os.path.join(input_dir, name)
        if name.endswith(".log") and os.path.isfile(path):
            info = read_file(path)
            if info and info["rows"]:
                by_station.setdefault(info["station"], []).append(info)
    stations = [build_station(by_station[s]) for s in sorted(by_station)]
    with open(output_file, "w") as handle:
        json.dump({"stations": stations}, handle, indent=1)


if __name__ == "__main__":
    main()
